      "title": "A Fresh Scenario, Both Skills",
      "instruction": "Read the case, then choose the best-reasoned response.",
      "question": "A sudden wave of nausea and lightheadedness hits during a crowded event, with a thought that it will just keep getting worse. What's the best-reasoned response?",
      "cases": [
        {
          "id": "case1",
          "name": "The crowded event",
          "text": "Sudden nausea and lightheadedness in a crowd, with a fear it will keep escalating.",
          "label": "The Case"
        }
      ],
      "options": [
        {
          "id": "both-skills",
          "label": "Relabel it as anxious arousal, not danger, and remember it has a physiological ceiling — it will peak and come back down within around 20-30 minutes"
        },
        {
          "id": "worsen",
          "label": "Assume it will keep getting worse and needs to be stopped immediately"
        }
      ],
      "feedbackMap": {
        "both-skills": {
          "title": "Right",
          "body": "Both skills together — the accurate relabel, and knowing there's a ceiling — directly counter the panic spiral.",
          "chain": [
            "The sensation is relabeled correctly.",
            "The ceiling fact counters 'it'll just get worse.'"
          ]
        },
        "worsen": {
          "title": "Not quite",
          "body": "This is the exact prediction l45 corrects — panic has a physiological ceiling and comes back down on its own.",
          "chain": [
            "The 'just keeps getting worse' prediction is the misconception this unit addresses."
          ],
          "counterTitle": "Try the ceiling fact",
          "counterBody": "Ask what actually happens to panic's intensity over a 20-30 minute window."
        }
      }
    }
  },
